do $$ begin create type public.match_mode as enum ('one_v_one','challenge','private_room','public_match'); exception when duplicate_object then null; end $$;
do $$ begin create type public.match_status as enum ('waiting','active','completed','cancelled'); exception when duplicate_object then null; end $$;
create table if not exists public.matches (id uuid primary key default gen_random_uuid(), mode public.match_mode not null, status public.match_status not null default 'waiting', host_user_id uuid not null references auth.users(id), max_players integer not null default 2 check(max_players between 2 and 100), question_ids uuid[] not null default '{}', current_question_index integer not null default 0, current_deadline timestamptz, reveal_at timestamptz, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.match_members (match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references auth.users(id) on delete cascade, ready boolean not null default false, is_host boolean not null default false, joined_at timestamptz not null default now(), disconnected_at timestamptz, left_at timestamptz, primary key(match_id,player_id));
create table if not exists public.match_answers (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references auth.users(id) on delete cascade, question_index integer not null, selected_option char(1), timed_out boolean not null default false, submitted_at timestamptz not null default now(), unique(match_id,player_id,question_index));
create index if not exists matches_status_idx on public.matches(status,created_at desc); create index if not exists match_members_player_idx on public.match_members(player_id); create index if not exists match_answers_round_idx on public.match_answers(match_id,question_index);
alter table public.matches enable row level security; alter table public.match_members enable row level security; alter table public.match_answers enable row level security;
create policy match_read_member on public.matches for select using(host_user_id=auth.uid() or exists(select 1 from public.match_members mm where mm.match_id=matches.id and mm.player_id=auth.uid()));
create policy member_read_self on public.match_members for select using(player_id=auth.uid());
create policy answer_read_self on public.match_answers for select using(player_id=auth.uid());
